const icons={brain:'<path d="M12 5c-2-4-7-2-6 2-4 0-5 6-2 8-2 4 2 7 5 5 1 3 3 1 3-1V5Zm0 0c2-4 7-2 6 2 4 0 5 6 2 8 2 4-2 7-5 5-1 3-3 1-3-1"/><path d="M6 7c0 3 3 2 3 5m-5 3c2-2 4-1 4 1m10-9c0 3-3 2-3 5m5 3c-2-2-4-1-4 1"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3c0-5 12-5 12 0v3M16 5c4 0 4 6 0 6m2 3c3 0 3 3 3 6"/>',clipboard:'<rect x="5" y="4" width="14" height="17" rx="2"/><rect x="9" y="2" width="6" height="4" rx="1"/><path d="M9 11h6m-6 4h6"/>',alert:'<path d="m10 4-8 14c-1 2 0 3 2 3h16c2 0 3-1 2-3L14 4c-1-2-3-2-4 0Z"/><path d="M12 9v5m0 3v.1"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',settings:'<path d="m9 3 6 0 1 3 3 1 2 5-2 4-3 1-1 4H9l-1-4-3-1-2-4 2-5 3-1Z"/><circle cx="12" cy="12" r="3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 0-1 1-1 2m0 3v.1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',bell:'<path d="M5 17h14l-2-3V9C17 2 7 2 7 9v5Zm5 3h4"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',shield:'<path d="m12 2 8 4v7c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',file:'<path d="M14 3H5v18h14V8Zm0 0v5h5M8 12h8m-8 4h6"/>',chevron:'<path d="m9 5 7 7-7 7"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const domains=[['memory','Memory','#9b85c8'],['attention','Attention','#6e9b8b'],['executive','Executive function','#8da9bd'],['processing','Processing speed','#c3a66d']];
const dates=['2026-06-10','2026-07-09','2026-08-12','2026-09-11','2026-10-14','2026-11-20'];
function seed(){const specs=[['Eleanor Bennett',72,'Female',[86,87,84,85],[68,82,75,78],480,589,'Hypertension; family history of cognitive impairment.','Reports increased difficulty recalling recent conversations. Independent with daily activities.'],['Robert Chen',68,'Male',[82,84,80,83],[81,85,82,83],510,502,'Type 2 diabetes; corrected vision.','Stable daily function. Regular walking routine.'],['Margaret Wilson',75,'Female',[83,80,82,81],[77,78,80,79],520,545,'Hypertension; hearing aid use.','Occasional word-finding difficulties reported.'],['James Anderson',64,'Male',[89,88,86,90],[90,88,87,91],420,415,'No relevant history reported.','Maintains usual activities and exercise.'],['Patricia Davis',71,'Female',[84,85,83,86],[80,70,79,81],495,568,'Sleep disturbance; medication review pending.','Variable attention reported; slept poorly before latest assessment.'],['Michael Thompson',69,'Male',[85,83,84,82],[84,84,85,83],460,452,'Controlled hypertension.','No new concerns reported.'],['Susan Martinez',66,'Female',[88,85,86,87],[86,84,85,85],450,467,'Migraine history.','Mild subjective memory concerns.'],['William Taylor',77,'Male',[80,82,79,81],[72,79,75,77],530,561,'Hearing loss; osteoarthritis.','Family reports occasional missed appointments.']];return specs.map((s,i)=>({id:`CT-${String(1001+i)}`,name:s[0],age:s[1],sex:s[2],history:s[7],notes:s[8],records:dates.map((date,j)=>{let r={date,notes:j===5?s[8]:'Scheduled cognitive follow-up.',reaction:Math.round(s[5]+(s[6]-s[5])*j/5),context:'Clinic · consistent protocol'};domains.forEach(([k],d)=>r[k]=Math.round(s[3][d]+(s[4][d]-s[3][d])*j/5+(j>0&&j<5?Math.sin(j+d)*1.2:0)));return r;})}));}
let data,reviewed,threshold;try{const saved=JSON.parse(localStorage.getItem('cognitivetrack-v1'));data=saved?.patients||seed();reviewed=saved?.reviewed||{};threshold=saved?.threshold||10;}catch{data=seed();reviewed={};threshold=10;}
let page='Overview',selected=data[0]?.id,query='',filter='all',range='6M',metric='all',pageNum=1;const perPage=6;
const patient=()=>data.find(p=>p.id===selected)||data[0];
const currentDay=()=>new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const recordProtocol=r=>r?.protocol||'manual-v1';
const protocolLabel=r=>recordProtocol(r)==='ct-games-v1'?'Games v1':'Manual scores';
const comparableRecords=p=>p.records.filter(r=>recordProtocol(r)===recordProtocol(p.records.at(-1)));
const recordBaseline=p=>comparableRecords(p)[0];
const latest=p=>p.records[p.records.length-1];const composite=r=>Math.round(domains.reduce((sum,[k])=>sum+r[k],0)/4);const fmt=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'});const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
function changes(p){if(comparableRecords(p).length<2)return [];const b=recordBaseline(p),l=latest(p);const c=domains.map(([key,label,color])=>({key,label,color,base:b[key],current:l[key],change:b[key]>0?(b[key]-l[key])/b[key]*100:null}));c.push({key:'reaction',label:'Reaction time',color:'#bc9d68',base:b.reaction,current:l.reaction,change:b.reaction>0?(l.reaction-b.reaction)/b.reaction*100:null});return c.filter(x=>x.change!==null).sort((a,b)=>b.change-a.change);}
function status(p){if(comparableRecords(p).length<2)return 'Baseline only';const c=changes(p)[0]?.change||0;return c>=threshold?'Review needed':c>=threshold/2?'Monitor':'Stable';}
function alerts(){return data.flatMap(p=>{let c=changes(p).filter(c=>c.change>=threshold);if(!c.length)return [];const key=p.id+'-'+latest(p).date+(recordProtocol(latest(p))==='ct-games-v1'?'-ct-games-v1':'');return [{p,changes:c,key,review:reviewed[key]}];}).sort((a,b)=>b.changes[0].change-a.changes[0].change);}
const badge=s=>`<span class="badge ${s==='Review needed'?'review':s==='Monitor'?'monitor':s==='Reviewed'?'reviewed':''}">${s}</span>`;
function persist(){try{localStorage.setItem('cognitivetrack-v1',JSON.stringify({patients:data,reviewed,threshold}));return true;}catch{toast('Browser storage is unavailable. Export your data to keep it.');return false;}}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),4000);}
function nav(p){page=p;query='';filter='all';pageNum=1;render();}
function render(){const unreviewed=alerts().filter(a=>!a.review).length;document.querySelector('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand">${icon('brain')}<span>CognitiveTrack<span style="color:#9cc7b7">.</span></span></div><div class="workspace-label">CLINICAL WORKSPACE</div><nav class="nav">${[['Overview','grid'],['Patients','users'],['Assessments','clipboard'],['Activities','brain'],['Review queue','alert'],['Reports','chart']].map(([n,i])=>`<button data-nav="${n}" class="${page===n?'active':''}" title="${n}">${icon(i)}<span>${n}</span>${n==='Review queue'&&unreviewed?`<b class="count">${unreviewed}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><strong>A clearer picture, over time.</strong>Connect each assessment to the person behind the numbers.<button data-action="method">${icon('help')} Understanding insights</button></div><nav class="nav" style="margin-top:20px"><button data-nav="Settings" aria-label="Settings" title="Settings" class="${page==='Settings'?'active':''}">${icon('settings')}<span>Settings</span></button></nav><div class="profile"><span class="avatar">SK</span><div><strong>Dr. Sarah Kim</strong><small>Demo clinician workspace</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">Workspace <span style="color:#bdc7c1">/</span> <b>${page}</b></div><div class="top-actions"><span>${icon('calendar')} &nbsp;25 November 2026</span><span class="demo-badge">Demo workspace</span><button class="notification" title="Open review queue" data-nav="Review queue">${icon('bell')}</button></div></header><div class="content"><div class="page-heading"><div><h1>${page==='Overview'?'A clearer view of cognitive health.':page==='Patients'?'Your patients, in perspective.':page==='Activities'?'Put cognition into play.':page==='Assessments'?'Every assessment tells a story.':page==='Review queue'?'Insights that deserve a closer look.':page==='Reports'?'Turn observations into understanding.':'Workspace settings'}</h1><p class="subtitle">${page==='Overview'?'Track meaningful changes. Understand patterns. Support better follow-up.':page==='Patients'?'Individual baselines. Longitudinal insight. Person-centered care.':page==='Activities'?'Interactive activities for memory, attention, flexibility, and speed.':page==='Assessments'?'A consistent record of cognitive performance over time.':page==='Review queue'?'Transparent signals to inform your clinical review.':page==='Reports'?'Take your longitudinal data and patient summaries with you.':'Configure your demonstration workspace.'}</p></div><div class="heading-buttons">${page==='Overview'||page==='Patients'?`<button class="button" data-action="export">${icon('download')} Export report</button>`:''}${['Overview','Assessments'].includes(page)?`<button class="button" data-nav="Activities">${icon('brain')} Play assessments</button>`:''}${['Overview','Patients','Assessments'].includes(page)?`<button class="button primary" data-action="${page==='Patients'?'patient-form':'assessment-form'}">${icon('plus')} ${page==='Patients'?'Add patient':'New assessment'}</button>`:''}</div></div>${page==='Overview'?overview():page==='Patients'?patientsView():page==='Activities'?GameUI.hub():page==='Assessments'?assessmentsView():page==='Review queue'?reviewView():page==='Reports'?reportsView():settingsView()}<footer class="footer"><span>${icon('shield')} Demo workspace · Stored in this browser</span><span>Supporting clinical judgment. Not a diagnostic tool.</span></footer></div></main></div>`;bind();}
function stats(){const n=alerts().filter(a=>!a.review).length;const total=data.reduce((n,p)=>n+p.records.length,0);const stable=data.filter(p=>status(p)==='Stable').length;return `<div class="stats">${[['Total patients',data.length,'users','',`${data.length} active longitudinal profiles`],['Assessments completed',total,'clipboard','',`Across ${new Set(data.flatMap(p=>p.records.map(r=>r.date.slice(0,7)))).size} assessment months`],['Awaiting review',n,'alert','amber',`${n} patients with flagged changes`],['Stable trajectories',stable,'chart','purple','Relative to individual baselines']].map(([l,v,i,c,n])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-icon ${c}">${icon(i)}</div><div class="stat-value">${v}</div><div class="stat-note">${l==='Stable trajectories'?'<span>Within demo threshold</span>':n}</div></div>`).join('')}</div>`;}
function overview(){return stats()+`<div class="grid-main">${patientPanel()}${alertPanel()}</div><div class="lower">${chartPanel()}${domainPanel()}</div>`;}
function filteredPatients(){return data.filter(p=>(p.name+' '+p.id).toLowerCase().includes(query.toLowerCase())&&(filter==='all'||status(p)===filter));}
function patientPanel(full=false){const rows=filteredPatients(),start=(pageNum-1)*perPage;return `<section class="panel"><div class="panel-head"><div><h2>${full?'Patient directory':'Patient overview'}</h2><p>Your patients’ latest cognitive performance at a glance.</p></div>${!full?'<button class="text-button" data-nav="Patients">View all patients</button>':''}</div><div class="toolbar"><label class="search">${icon('search')}<input id="patient-search" aria-label="Search patients" placeholder="Search patients by name or ID..." value="${esc(query)}"></label><select class="select" id="status-filter" aria-label="Filter patients by status">${[['all','All statuses'],['Review needed','Review needed'],['Monitor','Monitor'],['Stable','Stable'],['Baseline only','Baseline only']].map(([v,l])=>`<option value="${v}" ${v===filter?'selected':''}>${l}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th class="optional-col">Last assessment</th><th>Score / 100</th><th>Trend</th><th>Status</th><th></th></tr></thead><tbody>${rows.slice(start,start+perPage).map(p=>{const l=latest(p),d=l?composite(l)-composite(recordBaseline(p)):0;return `<tr data-patient="${p.id}" class="${selected===p.id?'selected':''}" tabindex="0" aria-label="Select ${esc(p.name)}"><td><div class="patient-cell"><span class="avatar" style="background:${['#e7eeea','#e8edf3','#f1e9df','#ebe9f4'][data.indexOf(p)%4]}">${initials(p.name)}</span><div><strong>${esc(p.name)}</strong><small>${p.id} &nbsp;·&nbsp; ${p.age} years</small></div></div></td><td class="optional-col">${l?fmt(l.date):'No assessments'}</td><td style="font-weight:600;color:#4b6354">${l?composite(l):'—'} <span style="font-size:11px;color:#a4ada5;font-weight:400">/ 100</span></td><td><span class="trend ${d<0?'down':''}">${d<0?'↘':d>0?'↗':'—'} ${Math.abs(d)} <small style="font-size:10px">pts</small></span></td><td>${badge(status(p))}</td><td><button title="Open patient details" data-detail="${p.id}">${icon('chevron')}</button></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No patients match your search.</td></tr>'}</tbody></table></div><div class="table-footer"><span>Showing ${rows.length?start+1:0}–${Math.min(start+perPage,rows.length)} of ${rows.length} patients</span><div class="pager">${Array.from({length:Math.ceil(rows.length/perPage)},(_,i)=>`<button data-page="${i+1}" class="${pageNum===i+1?'active':''}" aria-label="Patient page ${i+1}">${i+1}</button>`).join('')}</div></div></section>`;}
function patientsView(){return patientPanel(true)+`<div class="lower">${chartPanel()}${domainPanel()}</div>`;}
function alertPanel(){const a=alerts().filter(x=>!x.review);return `<section class="panel review-panel"><div class="panel-head"><h2>Needs your attention</h2>${icon('alert')}</div>${a.slice(0,2).map((a,i)=>alertCard(a,i)).join('')||'<div class="empty">You’re all caught up.<br>No pending review alerts.</div>'}<div class="review-footer"><button class="text-button" data-nav="Review queue">View review queue${a.length?' ('+a.length+')':''}</button></div></section>`;}
function alertCard(a,i=0){const c=a.changes[0];return `<article class="alert-card ${i%2?'purple':''}"><div class="alert-top"><strong>${a.review?'Reviewed':'Baseline deviation'}</strong><span>${fmt(latest(a.p).date).replace(' 2026','')}</span></div><h3>${esc(a.p.name)}</h3><p>${c.label} ${c.key==='reaction'?'slowed':'declined'} ${c.change.toFixed(1)}% from baseline.${a.changes.length>1?` ${a.changes.length} indicators flagged.`:''}</p><button class="text-button" data-alert="${a.p.id}">${a.review?'View review':'Review insight'}</button></article>`;}
function chartPanel(){const p=patient();if(!p)return '';return `<section class="panel"><div class="panel-head"><div><div class="trend-heading"><h2>Cognitive trajectory</h2></div><p>${esc(p.name)} <span style="color:#c3ccc5">&nbsp; / &nbsp;</span> ${comparableRecords(p).length} ${comparableRecords(p).length===1?'assessment':'assessments'} · ${protocolLabel(latest(p))}</p></div><div class="chart-controls"><select id="chart-metric" class="select" aria-label="Chart domain"><option value="all">All domains</option>${domains.map(([k,l])=>`<option value="${k}" ${metric===k?'selected':''}>${l}</option>`).join('')}</select><div class="segments">${['3M','6M','All'].map(x=>`<button data-range="${x}" class="${range===x?'active':''}">${x}</button>`).join('')}</div></div></div><div class="chart-legend">${domains.filter(([k])=>metric==='all'||k===metric).map(([k,l,c])=>`<span class="legend-item"><i class="legend-line" style="background:${c}"></i>${l}</span>`).join('')}<span class="legend-item"><i class="legend-line" style="background:#c8cfc9"></i>Baseline${metric==='all'?' composite':''}</span></div><div class="chart-container">${chartSvg(p)}</div><div class="chart-caption">${icon('help')} Scores out of 100 · Same-protocol baseline only</div></section>`;}
function chartSvg(p){if(!p.records.length)return '<div class="empty">Add an assessment to establish a baseline.</div>';const end=new Date(latest(p).date+'T12:00:00'),cutoff=new Date(end);if(range!=='All')cutoff.setMonth(end.getMonth()-(range==='3M'?3:6));const records=comparableRecords(p).filter(r=>range==='All'||new Date(r.date+'T12:00:00')>=cutoff);const x=r=>{const min=new Date(records[0].date).getTime(),max=new Date(records.at(-1).date).getTime();return max===min?350:45+(new Date(r.date).getTime()-min)/(max-min)*625;};const values=records.flatMap(r=>domains.filter(([k])=>metric==='all'||k===metric).map(([k])=>r[k]));const baseline=metric==='all'?composite(recordBaseline(p)):recordBaseline(p)[metric];const low=Math.max(0,Math.floor((Math.min(...values,baseline)-10)/10)*10),y=v=>155-(v-low)/(100-low)*132;return `<svg viewBox="0 0 710 195" role="img" aria-label="${esc(p.name)} cognitive score trends from ${fmt(records[0].date)} to ${fmt(records.at(-1).date)}"><defs><linearGradient id="shade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#a6bbac" stop-opacity=".1"/><stop offset="1" stop-color="#a6bbac" stop-opacity="0"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const v=low+(100-low)*i/4;return `<line x1="45" x2="680" y1="${y(v)}" y2="${y(v)}" stroke="#edf1ed"/><text x="30" y="${y(v)+4}" text-anchor="end" fill="#9aa79e" font-size="11">${Math.round(v)}</text>`;}).join('')}<line x1="45" x2="680" y1="${y(baseline)}" y2="${y(baseline)}" stroke="#b5bfb7" stroke-dasharray="5 5"/><text x="679" y="${y(baseline)-5}" text-anchor="end" fill="#99a599" font-size="9">Baseline ${baseline}</text>${domains.filter(([k])=>metric==='all'||k===metric).map(([k,label,c])=>`<polyline points="${records.map(r=>`${x(r)},${y(r[k])}`).join(' ')}" stroke="${c}" stroke-width="2.4" stroke-linejoin="round" fill="none"/>${records.map(r=>`<circle cx="${x(r)}" cy="${y(r[k])}" r="3.2" fill="white" stroke="${c}" stroke-width="1.7"><title>${fmt(r.date)} · ${label}: ${r[k]}/100</title></circle>`).join('')}`).join('')}${records.filter((r,i)=>records.length<9||i%Math.ceil(records.length/7)===0||i===records.length-1).map(r=>`<text x="${x(r)}" y="180" text-anchor="middle" fill="#9aa79e" font-size="11">${new Date(r.date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</text>`).join('')}</svg>`;}
function domainPanel(){const p=patient();if(!p)return '';const l=latest(p);return `<section class="panel domain-panel"><div class="panel-head"><div><h2>Domain snapshot</h2><p>Latest assessment${l?' · '+fmt(l.date).replace(' 2026',''):''}</p></div></div><div class="domains">${domains.map(([k,n,c])=>`<div class="domain-row"><div class="domain-label"><span>${n}</span><strong>${l?l[k]:'—'} <span style="color:#adb6ae;font-weight:400">/ 100</span></strong></div><div class="bar"><span style="width:${l?l[k]:0}%;background:${c}"></span></div></div>`).join('')}</div><div class="domain-foot">${l?`Reaction time <strong style="float:right;color:#6b8170">${l.reaction} ms</strong><br>Compared with ${recordBaseline(p).reaction} ms at baseline.`:'No assessment recorded yet.'}</div></section>`;}
function assessmentsView(){const records=data.flatMap(p=>p.records.map(r=>({p,r}))).sort((a,b)=>b.r.date.localeCompare(a.r.date));return `<section class="panel"><div class="panel-head"><div><h2>Assessment history</h2><p>${records.length} records · Select a patient to inspect their longitudinal history.</p></div><button class="button" data-action="csv">${icon('download')} Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Patient</th><th>Date</th><th>Protocol</th>${domains.map(([,l])=>`<th>${l}</th>`).join('')}<th>Reaction time</th><th>Composite</th></tr></thead><tbody>${records.map(({p,r})=>`<tr data-detail="${p.id}" tabindex="0"><td style="color:#42614b">${esc(p.name)}</td><td>${fmt(r.date)}</td><td>${protocolLabel(r)}</td>${domains.map(([k])=>`<td>${r[k]}</td>`).join('')}<td>${r.reaction} ms</td><td>${composite(r)} / 100</td></tr>`).join('')}</tbody></table></div></section>`;}
function reviewView(){const as=alerts(),pending=as.filter(a=>!a.review),done=as.filter(a=>a.review);return `<p class="view-description">${pending.length} pending reviews · Alerts use a configurable ${threshold}% deterioration threshold against each patient’s first assessment of the same protocol. These demonstration rules are not clinically validated.</p><div class="full-grid">${pending.map(alertCard).join('')||'<div class="panel empty">No pending reviews.</div>'}</div>${done.length?`<h2 style="margin:30px 0 20px">Reviewed (${done.length})</h2><div class="full-grid">${done.map(alertCard).join('')}</div>`:''}`;}
function reportsView(){return `<div class="full-grid">${[['file','Patient summary','A readable report with baseline comparisons, domain scores, history, and review notes.','Download patient report','export'],['clipboard','Assessment dataset','All recorded assessments, including reaction times and contextual notes, in CSV format.','Download CSV','csv'],['download','Workspace backup','Save all demonstration patients, assessments, review notes, and your threshold settings.','Download JSON','json']].map(([i,h,p,b,a])=>`<section class="panel report-card">${icon(i)}<h2>${h}</h2><p>${p}</p><button class="button" data-action="${a}">${icon('download')} ${b}</button></section>`).join('')}</div><section class="panel settings" style="margin-top:24px"><h2>Selected patient</h2><p>Choose the patient to include in your summary report.</p><select id="report-patient" class="select">${data.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${p.id}</option>`).join('')}</select></section>`;}
function settingsView(){return `<section class="panel settings"><h2>Review alert rules</h2><p>The first recorded assessment using the latest record’s protocol is the individual baseline. Manual scores and Games v1 scores are kept separate. A review alert appears when any domain score decreases, or reaction time increases, by the threshold below. Monitor status begins at half this threshold. Composite scores are the unweighted average of four domains.</p><form id="settings-form"><label class="field">Demonstration review threshold (%)<input type="number" name="threshold" min="1" max="50" step="1" value="${threshold}" required></label><p>These rules flag changes for human review; they do not establish statistical significance, reliable change, or a diagnosis. Sleep, testing conditions, medications, practice effects, and measurement variability require clinical interpretation.</p><button class="button primary" type="submit">Save threshold</button></form><h3>Data and privacy</h3><p>This prototype stores synthetic records locally in your browser. It has no clinical backend, patient identity verification, or shared access. Use demonstration data only. Export a backup before clearing your browser storage.</p><button class="button" data-action="json">${icon('download')} Export workspace backup</button><h3>Restore a backup</h3><p>Restore a CognitiveTrack JSON export. This replaces the demonstration records in this browser after confirmation.</p><input id="restore-file" type="file" accept="application/json,.json" aria-label="Restore JSON backup"></section>`;}
function bind(){if(page==='Activities')GameUI.bind();document.querySelectorAll('[data-nav]').forEach(e=>e.onclick=()=>nav(e.dataset.nav));document.querySelectorAll('[data-action]').forEach(e=>e.onclick=()=>actions[e.dataset.action]?.());document.querySelectorAll('[data-patient]').forEach(e=>{const select=()=>{selected=e.dataset.patient;render();};e.onclick=select;e.onkeydown=k=>{if(k.key==='Enter')select();};});document.querySelectorAll('[data-detail]').forEach(e=>{e.onclick=ev=>{ev.stopPropagation();showPatient(e.dataset.detail);};e.onkeydown=ev=>{if(ev.key==='Enter'){ev.stopPropagation();showPatient(e.dataset.detail);}};});document.querySelectorAll('[data-alert]').forEach(e=>e.onclick=()=>showAlert(e.dataset.alert));document.querySelectorAll('[data-page]').forEach(e=>e.onclick=()=>{pageNum=Number(e.dataset.page);render();});document.querySelectorAll('[data-range]').forEach(e=>e.onclick=()=>{range=e.dataset.range;render();});const search=document.querySelector('#patient-search');if(search)search.oninput=()=>{const start=search.selectionStart;query=search.value;pageNum=1;render();const next=document.querySelector('#patient-search');next.focus();next.setSelectionRange(start,start);};const sf=document.querySelector('#status-filter');if(sf)sf.onchange=()=>{filter=sf.value;pageNum=1;render();};const cm=document.querySelector('#chart-metric');if(cm)cm.onchange=()=>{metric=cm.value;render();};const rp=document.querySelector('#report-patient');if(rp)rp.onchange=()=>selected=rp.value;const form=document.querySelector('#settings-form');if(form)form.onsubmit=e=>{e.preventDefault();threshold=Number(new FormData(form).get('threshold'));const saved=persist();render();if(saved)toast('Review threshold updated. Alerts recalculated.');};const restore=document.querySelector('#restore-file');if(restore)restore.onchange=()=>restoreBackup(restore.files[0]);}
let lastFocus;function modal(title,body){lastFocus=document.activeElement;document.querySelector('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button class="modal-close" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div></section></div>`;document.querySelector('.modal-close').onclick=closeModal;document.querySelector('.modal-overlay').onclick=e=>{if(e.target.classList.contains('modal-overlay'))closeModal();};setTimeout(()=>document.querySelector('.modal-body input,.modal-body select,.modal-close')?.focus(),0);}
function closeModal(){document.querySelector('#modal-root').innerHTML='';lastFocus?.focus();}document.addEventListener('keydown',e=>{const m=document.querySelector('.modal');if(!m)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focusable=[...m.querySelectorAll('button,input,select,textarea,a')].filter(e=>!e.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function assessmentForm(){modal('New cognitive assessment',`<form id="assessment-form"><div class="form-grid"><label class="field full">Patient<select name="patient">${data.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${esc(p.name)} · ${p.id}</option>`).join('')}</select></label><label class="field">Assessment date<input type="date" name="date" value="${currentDay()}" max="${currentDay()}" required></label><label class="field">Reaction time (milliseconds)<input type="number" name="reaction" min="100" max="10000" step="1" placeholder="e.g. 480" required></label>${domains.map(([k,l])=>`<label class="field">${l} (0–100)<input type="number" name="${k}" min="0" max="100" step="1" required placeholder="Score / 100"></label>`).join('')}<label class="field full">Testing conditions<input name="context" maxlength="250" placeholder="e.g. Clinic, rested, usual medication"></label><label class="field full">Assessment notes<textarea name="notes" maxlength="2000" placeholder="Relevant observations, symptoms, and follow-up considerations"></textarea></label></div><p class="form-note">Enter scores from a consistent assessment protocol. All four domains are required; partial assessments are not scored. A patient’s first chronological record for each protocol establishes its baseline.</p><div id="form-error" role="alert" style="font-size:13px;color:#a16240"></div><div class="modal-actions"><button type="button" class="button" id="cancel-form">Cancel</button><button class="button primary" type="submit">Save assessment</button></div></form>`);document.querySelector('#cancel-form').onclick=closeModal;document.querySelector('#assessment-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p=data.find(p=>p.id===f.get('patient')),date=f.get('date');if(p.records.some(r=>r.date===date&&recordProtocol(r)==='manual-v1')){document.querySelector('#form-error').textContent='This patient already has an assessment on this date. Choose a different date.';return;}const r={date,protocol:'manual-v1',completedAt:new Date().toISOString(),reaction:Number(f.get('reaction')),context:f.get('context').trim(),notes:f.get('notes').trim()};domains.forEach(([k])=>r[k]=Number(f.get(k)));p.records.push(r);p.records.sort((a,b)=>a.date.localeCompare(b.date)||(a.completedAt||'').localeCompare(b.completedAt||''));Object.keys(reviewed).filter(k=>k.startsWith(p.id+'-')).forEach(k=>delete reviewed[k]);selected=p.id;const saved=persist();closeModal();render();if(saved)toast('Assessment saved. Trajectory and alerts updated.');};}
function patientForm(){modal('Add a patient',`<form id="patient-form"><div class="form-grid"><label class="field full">Patient name<input name="name" required maxlength="80" placeholder="Use a fictional name"></label><label class="field">Age (years)<input name="age" type="number" min="18" max="120" required></label><label class="field">Sex<select name="sex"><option>Female</option><option>Male</option><option>Not specified</option></select></label><label class="field full">Relevant history<textarea name="history" maxlength="2000" placeholder="Medical, family, and medication history"></textarea></label><label class="field full">Patient notes<textarea name="notes" maxlength="2000" placeholder="Presenting concerns and functional observations"></textarea></label></div><p class="form-note">Demo workspace: enter synthetic patient information only.</p><div class="modal-actions"><button class="button primary" type="submit">Create patient</button></div></form>`);document.querySelector('#patient-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(!f.get('name').trim())return;const id='CT-'+(Math.max(1000,...data.map(p=>Number(p.id.split('-')[1])||1000))+1);data.push({id,name:f.get('name').trim(),age:Number(f.get('age')),sex:f.get('sex'),history:f.get('history').trim(),notes:f.get('notes').trim(),records:[]});selected=id;const saved=persist();closeModal();render();if(saved)toast('Patient added. Add an assessment to establish a baseline.');};}
function showPatient(id){selected=id;const p=patient(),l=latest(p);modal(esc(p.name),`<div class="detail-summary"><span class="avatar">${initials(p.name)}</span><div><h3>${p.id} · ${p.age} years · ${esc(p.sex)}</h3><p>${p.records.length} assessments${p.records.length?' · Baseline '+fmt(recordBaseline(p).date):''}</p></div>${badge(status(p))}</div><div class="detail-section"><h3>Relevant history</h3><p>${esc(p.history||'No history recorded.')}</p></div><div class="detail-section"><h3>Patient notes</h3><p>${esc(p.notes||'No notes recorded.')}</p></div>${l?`<div class="numbers"><div class="number"><b>${composite(l)}</b>Latest composite / 100</div><div class="number"><b>${composite(recordBaseline(p))}</b>Baseline composite</div><div class="number"><b>${l.reaction}</b>Reaction time · ms</div></div>`:''}<div class="detail-section"><h3>Assessment timeline</h3>${p.records.slice().reverse().map(r=>`<div style="margin:14px 0"><strong style="font-size:13px">${fmt(r.date)} · ${protocolLabel(r)} · ${composite(r)}/100</strong><p>${esc(r.notes||'No notes recorded.')}</p><small style="color:#97a497">${esc(r.context||'Conditions not recorded')}</small></div>`).join('')||'<p>No assessments recorded.</p>'}</div><div class="modal-actions"><button class="button" id="detail-export">${icon('download')} Export report</button><button class="button primary" id="detail-assess">${icon('plus')} Add assessment</button></div>`);document.querySelector('#detail-export').onclick=exportReport;document.querySelector('#detail-assess').onclick=assessmentForm;render();}
function showAlert(id){const a=alerts().find(a=>a.p.id===id);if(!a)return;const p=a.p;modal('Review cognitive change',`<div class="detail-summary"><span class="avatar">${initials(p.name)}</span><div><h3>${esc(p.name)}</h3><p>${p.id} · Latest assessment ${fmt(latest(p).date)}</p></div></div><div class="notice">${a.changes.length} indicator${a.changes.length>1?'s':''} exceeded the ${threshold}% demonstration threshold. This signal is a prompt for clinician review, not a diagnosis or a statistically validated change.</div><div class="table-wrap" style="margin:20px 0"><table><thead><tr><th>Indicator</th><th>Baseline</th><th>Latest</th><th>Change</th></tr></thead><tbody>${a.changes.map(c=>`<tr><td>${c.label}</td><td>${c.base}${c.key==='reaction'?' ms':''}</td><td>${c.current}${c.key==='reaction'?' ms':''}</td><td style="color:#b2804d">${c.change.toFixed(1)}% ${c.key==='reaction'?'slower':'lower'}</td></tr>`).join('')}</tbody></table></div><div class="detail-section"><h3>Why this was flagged</h3><p>Compared with the first assessment of the same protocol on ${fmt(recordBaseline(p).date)}. Score deterioration = (baseline − latest) ÷ baseline × 100. Reaction-time deterioration = (latest − baseline) ÷ baseline × 100. A zero score baseline is excluded from relative-change calculations.</p></div><div class="detail-section"><h3>Assessment context</h3><p>${esc(latest(p).notes||'No notes recorded.')}</p><p>${esc(latest(p).context||'Testing conditions not recorded.')}</p></div>${a.review?`<div class="detail-section"><h3>Review recorded · ${new Date(a.review.date).toLocaleDateString('en-GB')}</h3><p>${esc(a.review.note)}</p></div><button class="button" id="reopen-review">Reopen review</button>`:`<form id="review-form"><label class="field">Clinical review note<textarea name="note" maxlength="2000" placeholder="Record your interpretation and follow-up plan" required></textarea></label><div class="modal-actions"><button class="button primary" type="submit">${icon('check')} Mark reviewed</button></div></form>`}`);const form=document.querySelector('#review-form');if(form)form.onsubmit=e=>{e.preventDefault();const note=new FormData(form).get('note').trim();if(!note)return;reviewed[a.key]={date:new Date().toISOString(),note};const saved=persist();closeModal();render();if(saved)toast('Review recorded. Patient trajectory remains available.');};const reopen=document.querySelector('#reopen-review');if(reopen)reopen.onclick=()=>{delete reviewed[a.key];persist();closeModal();render();toast('Review reopened.');};}
function download(name,type,body){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('Report downloaded.');}
function exportCSV(){const cell=x=>'"'+String(x??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Patient ID','Patient name','Age','Date','Protocol','Memory','Attention','Executive function','Processing speed','Reaction time (ms)','Composite','Testing conditions','Notes'],...data.flatMap(p=>p.records.map(r=>[p.id,p.name,p.age,r.date,protocolLabel(r),...domains.map(([k])=>r[k]),r.reaction,composite(r),r.context,r.notes]))];download('cognitivetrack-assessments.csv','text/csv;charset=utf-8','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'));}
function exportReport(){const p=patient();if(!p){toast('Add a patient first.');return;}const b=recordBaseline(p),l=latest(p),a=alerts().find(a=>a.p.id===p.id);download(`CognitiveTrack-${p.id}-report.html`,'text/html;charset=utf-8',`<!doctype html><html lang="en"><meta charset="UTF-8"><title>CognitiveTrack · ${esc(p.name)}</title><style>body{font:15px system-ui;color:#294235;max-width:900px;margin:50px auto;padding:20px;line-height:1.6}h1{color:#246452}h2{margin-top:30px}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid #ddd;text-align:left}.note{padding:15px;background:#f4f5ed}small{color:#77887b}@media print{body{margin:0}}</style><h1>CognitiveTrack</h1><p>Longitudinal cognitive assessment summary</p><h2>${esc(p.name)}</h2><p>${p.id} · ${p.age} years · ${esc(p.sex)}</p><p class="note">Synthetic demonstration data. Not for diagnosis. Scores and thresholds have not been clinically validated. Data stored only in the originating browser.</p><h2>Patient history</h2><p>${esc(p.history||'Not recorded.')}</p><p>${esc(p.notes||'No patient notes.')}</p>${l?`<p>Baseline: ${fmt(b.date)} · Latest: ${fmt(l.date)} · ${p.records.length} assessments</p><h2>Domain comparison</h2><table><tr><th>Domain</th><th>Baseline</th><th>Latest</th></tr>${domains.map(([k,label])=>`<tr><td>${label}</td><td>${b[k]}</td><td>${l[k]}</td></tr>`).join('')}<tr><td>Reaction time</td><td>${b.reaction} ms</td><td>${l.reaction} ms</td></tr><tr><td>Composite / 100</td><td>${composite(b)}</td><td>${composite(l)}</td></tr></table>`:'<p>No assessment recorded.</p>'}<h2>Review signals</h2><p>Status: ${status(p)}. Demonstration threshold: ${threshold}%.</p>${a?`<ul>${a.changes.map(c=>`<li>${c.label}: ${c.change.toFixed(1)}% deterioration (${c.base} → ${c.current})</li>`).join('')}</ul><p>Review: ${a.review?esc(a.review.note):'Pending clinician review.'}</p>`:'<p>No indicators exceed the configured threshold.</p>'}<h2>Assessment timeline</h2>${p.records.map(r=>`<h3>${fmt(r.date)} · ${protocolLabel(r)} · ${composite(r)}/100</h3><p>${esc(r.notes||'No notes recorded.')}</p><small>${esc(r.context||'Conditions not recorded.')}</small>`).join('')}<h2>Method and limitations</h2><p>Baseline is the first chronological assessment of the same protocol as the latest record. Games v1 and manual scores are not mixed. Composite is the unweighted mean of four domain scores. Domain decline = (baseline − latest) / baseline × 100; reaction slowing = (latest − baseline) / baseline × 100. Zero score baselines are excluded from relative comparisons. Monitor status begins at half the review threshold. These rules do not account for measurement error, practice effects, age norms or clinical confounders and do not determine statistical significance.</p></html>`);}
function validBackup(v){return v&&Array.isArray(v.patients)&&v.patients.length>0&&v.patients.length<=1000&&Number.isInteger(v.threshold)&&v.threshold>=1&&v.threshold<=50&&new Set(v.patients.map(p=>p.id)).size===v.patients.length&&v.patients.every(p=>typeof p.id==='string'&&/^CT-\d+$/.test(p.id)&&typeof p.name==='string'&&p.name.trim()&&p.name.length<=80&&Number.isInteger(p.age)&&p.age>=18&&p.age<=120&&typeof p.sex==='string'&&typeof p.history==='string'&&typeof p.notes==='string'&&Array.isArray(p.records)&&new Set(p.records.map(r=>r.date+recordProtocol(r))).size===p.records.length&&p.records.every(r=>(!r.protocol||['manual-v1','ct-games-v1'].includes(r.protocol))&&typeof r.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&!isNaN(Date.parse(r.date))&&new Date(r.date).toISOString().slice(0,10)===r.date&&r.date<=currentDay()&&domains.every(([k])=>Number.isInteger(r[k])&&r[k]>=0&&r[k]<=100)&&Number.isInteger(r.reaction)&&r.reaction>=100&&r.reaction<=10000&&typeof r.context==='string'&&typeof r.notes==='string'))&&v.reviewed&&typeof v.reviewed==='object'&&!Array.isArray(v.reviewed)&&Object.values(v.reviewed).every(r=>r&&typeof r.note==='string'&&typeof r.date==='string'&&!isNaN(Date.parse(r.date)));}
async function restoreBackup(file){if(!file)return;try{if(file.size>5000000)throw Error();const v=JSON.parse(await file.text());if(!validBackup(v))throw Error();modal('Restore workspace backup',`<p class="view-description">Replace the current demonstration workspace with ${v.patients.length} patients from this backup? Export your current workspace first if you want to keep it.</p><div class="modal-actions"><button class="button" id="restore-cancel">Cancel</button><button class="button primary" id="restore-confirm">Replace and restore</button></div>`);document.querySelector('#restore-cancel').onclick=closeModal;document.querySelector('#restore-confirm').onclick=()=>{data=v.patients;data.forEach(p=>p.records.sort((a,b)=>a.date.localeCompare(b.date)||(a.completedAt||'').localeCompare(b.completedAt||'')));reviewed=v.reviewed;threshold=v.threshold;selected=data[0].id;const saved=persist();closeModal();render();if(saved)toast('Workspace restored.');};}catch{toast('Invalid backup. Select a valid CognitiveTrack JSON export.');}}
const actions={'assessment-form':assessmentForm,'patient-form':patientForm,export:exportReport,csv:exportCSV,json:()=>download('cognitivetrack-backup.json','application/json',JSON.stringify({patients:data,reviewed,threshold},null,2)),method:()=>modal('Understanding cognitive insights',`<div class="detail-section"><h3>A baseline that belongs to the patient</h3><p>Each patient’s first chronological assessment within the same protocol is their baseline. Later assessments are compared with that reference using the same four score domains and reaction-time metric.</p></div><div class="detail-section"><h3>Transparent demonstration rules</h3><p>Review is flagged at ${threshold}% deterioration in any domain or reaction time. Monitor status begins at ${threshold/2}%. The composite is the unweighted average of four scores. Alert details show the numbers and calculation behind each flag.</p></div><div class="notice">These are illustrative, unvalidated thresholds. Observed change is not necessarily meaningful clinical decline. Consider testing conditions, measurement variability, symptoms, functional changes, and the patient’s clinical history before interpreting a signal.</div><div class="detail-section"><h3>Designed for a human review</h3><p>Record your interpretation and follow-up plan in the review queue. Marking an alert reviewed retains the underlying score and trend.</p></div>`)};
render();


